def maxAverageOfPath(matrix):
    """
    Computes the maximum average cost of a path from the top-left to the
    bottom-right corner of a square matrix, moving only right or down.
    Since every such path contains exactly 2*N-1 cells, maximizing the
    average is equivalent to maximizing the total sum of the path.
    """
    if not matrix or not matrix[0]:
        return 0.0  # or raise ValueError("Empty matrix")

    n = len(matrix)
    # dp[j] will hold the maximum sum to reach cell (current_row, j)
    dp = [0] * n

    for i in range(n):
        for j in range(n):
